-- 세트 375: 여러 컨테이너가 든 Pod 손연습: 컨테이너 둘 만들기, logs·exec -c, emptyDir 공유, initContainers
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_k8s_multicontainer_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (375, 1, '컨테이너 두 개짜리 Pod 만들기', '**배경** — 한 Pod 안에는 컨테이너를 **여러 개** 둘 수 있습니다. 같은 Pod 의 컨테이너는 **네트워크(localhost)를 함께 쓰고**, 볼륨을 **같이 마운트** 해 파일을 주고받을 수 있습니다. 앱 옆에서 로그를 모으거나 설정을 준비해 주는 보조 컨테이너를 붙이는 데 씁니다. 이 세트의 문제는 연습용 네임스페이스에서 하며, `kubectl` 은 이미 그 네임스페이스를 기본으로 씁니다(이미지는 `busybox:1.36`, `nginx:1.25`). 문제마다 처음 상태에서 다시 시작하고, 일부 문제는 미리 만들어 둔 Pod 를 줍니다.

**문제** — YAML 로 Pod **`mc375-two`** 를 만드세요. 컨테이너는 이 순서로 두 개: 이름 **`web`**(이미지 `nginx:1.25`), 이름 **`helper`**(이미지 `busybox:1.36`, 명령 `sh -c "sleep 3600"` 으로 계속 떠 있게). Pod 가 Running 이 되고 컨테이너가 둘 다 준비(Ready)되어야 합니다.', '`containers:` 아래에 `- name: ...` 항목을 **두 개** 나란히 적습니다. busybox 는 명령이 끝나면 컨테이너도 끝나므로 `command: ["sh", "-c", "sleep 3600"]` 처럼 계속 도는 명령을 주세요.', 'kubectl apply -n $NS -f - <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: mc375-two
spec:
  containers:
  - name: web
    image: nginx:1.25
  - name: helper
    image: busybox:1.36
    command: ["sh", "-c", "sleep 3600"]
EOF
kubectl get pod mc375-two -n $NS   # READY 2/2

# containers 목록에 항목을 둘 쓰면 한 Pod 에 컨테이너가 둘 뜬다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.spec.containers[*].name}'' 2>/dev/null)\\" = \\"web helper\\" ] ) && ( [ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.spec.containers[0].image}-{.spec.containers[1].image}'' 2>/dev/null)\\" = \\"nginx:1.25-busybox:1.36\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.status.containerStatuses[?(@.ready==true)].name}'' 2>/dev/null | wc -w | tr -d '' '')\\" = 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컨테이너 이름이 web, helper 순서다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.spec.containers[*].name}'' 2>/dev/null)\\" = \\"web helper\\" ]"]}, {"label": "이미지가 nginx:1.25, busybox:1.36 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.spec.containers[0].image}-{.spec.containers[1].image}'' 2>/dev/null)\\" = \\"nginx:1.25-busybox:1.36\\" ]"]}, {"label": "두 컨테이너가 모두 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod mc375-two -n $NS -o jsonpath=''{.status.containerStatuses[?(@.ready==true)].name}'' 2>/dev/null | wc -w | tr -d '' '')\\" = 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 2, 'Pod 안의 컨테이너 이름 읽어 저장하기', 'Pod **`mc375-reader`** 에는 컨테이너가 여러 개 있습니다. 컨테이너 **이름들만** 출력하는 `-o jsonpath` 를 만들어 그 결과를 **`/tmp/q2.txt`** 에 저장하세요. (이름 사이는 공백이면 됩니다)', '`kubectl get pod 이름 -o yaml` 에서 `spec.containers` 의 모양을 보고, 모든 항목의 이름을 뽑으려면 `[*]` 를 씁니다(`{.spec.containers[*].name}`).', 'kubectl get pod mc375-reader -n $NS -o jsonpath=''{.spec.containers[*].name}'' > /tmp/q2.txt
cat /tmp/q2.txt

# containers[*] 는 모든 컨테이너, .name 은 이름이다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-reader\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - name: app\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n  - name: logger\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod/mc375-reader -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/q2.txt)\\" = \\"app logger\\" ] ) && ( [ \\"$(kubectl get pod mc375-reader -n $NS -o jsonpath=''{.metadata.name}'' 2>/dev/null)\\" = \\"mc375-reader\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 컨테이너 이름 두 개(app logger)다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q2.txt)\\" = \\"app logger\\" ]"]}, {"label": "Pod 는 그대로 있다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-reader -n $NS -o jsonpath=''{.metadata.name}'' 2>/dev/null)\\" = \\"mc375-reader\\" ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 3, '컨테이너 하나의 로그만 보기 (kubectl logs -c)', 'Pod **`mc375-logs`** 에는 컨테이너 `a` 와 `b` 가 있고, 각자 한 줄씩 출력했습니다. **컨테이너 `b` 의 로그만** 읽어 **`/tmp/q3.txt`** 에 저장하세요.', 'Pod 에 컨테이너가 여러 개면 `kubectl logs 파드` 만으로는 어느 컨테이너인지 모릅니다. `-c 컨테이너이름` 으로 고르세요.', 'kubectl logs mc375-logs -c b -n $NS > /tmp/q3.txt
cat /tmp/q3.txt

# -c 로 컨테이너를 고른다. 안 고르면 기본 컨테이너를 쓰거나 오류가 난다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-logs\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - name: a\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo from-a; sleep 3600\\"]\\n  - name: b\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo from-b; sleep 3600\\"]\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod/mc375-logs -n $NS --timeout=90s >/dev/null 2>&1; sleep 2; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/q3.txt)\\" = from-b ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q3.txt 가 컨테이너 b 의 로그(from-b)다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q3.txt)\\" = from-b ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 4, '컨테이너를 골라 명령 실행하기 (kubectl exec -c)', 'Pod **`mc375-role`** 에는 컨테이너 `main` 과 `sidecar` 가 있고, 각자 환경 변수 `ROLE` 이 다르게 정해져 있습니다. **`sidecar` 컨테이너 안에서** `echo $ROLE` 을 실행한 출력을 **`/tmp/q4.txt`** 에 저장하세요. (내 쉘이 아니라 컨테이너 안의 쉘이 `$ROLE` 을 해석해야 합니다)', '`kubectl exec 파드 -c 컨테이너 -- 명령` 형태입니다. `$ROLE` 을 컨테이너 안에서 해석하려면 `sh -c ''echo $ROLE''` 처럼 작은따옴표로 감싸 명령으로 넘기세요.', 'kubectl exec mc375-role -c sidecar -n $NS -- sh -c ''echo $ROLE'' > /tmp/q4.txt
cat /tmp/q4.txt

# -c 로 컨테이너를 고르고, -- 뒤가 컨테이너 안에서 실행할 명령이다. 작은따옴표로 $ROLE 을 컨테이너 쉘에 넘긴다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-role\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n    env:\\n    - name: ROLE\\n      value: main\\n  - name: sidecar\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n    env:\\n    - name: ROLE\\n      value: sidecar\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod/mc375-role -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/q4.txt)\\" = sidecar ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 가 sidecar 컨테이너의 ROLE 값(sidecar)이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q4.txt)\\" = sidecar ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 5, '컨테이너끼리 파일 주고받기 (emptyDir 공유)', '**배경** — `emptyDir` 볼륨은 Pod 가 뜰 때 만들어지는 빈 디렉터리로, 같은 Pod 의 컨테이너들이 **같이 마운트** 하면 파일을 주고받을 수 있습니다.

**문제** — Pod **`mc375-share`** 를 YAML 로 만드세요. ① `emptyDir` 볼륨 **`shared`**. ② 컨테이너 **`writer`**(`busybox:1.36`)는 `shared` 를 `/data` 에 마운트하고 `echo hello > /data/msg.txt` 를 한 뒤 `sleep 3600`. ③ 컨테이너 **`reader`**(`busybox:1.36`, `sleep 3600`)도 `shared` 를 `/data` 에 마운트. `reader` 안에서 `/data/msg.txt` 를 읽으면 `hello` 가 나와야 합니다.', '`spec.volumes` 에 `- name: shared` 와 `emptyDir: {}` 를 적고, 두 컨테이너 모두 `volumeMounts` 에 `name: shared`, `mountPath: /data` 를 적습니다. 볼륨은 컨테이너 목록과 같은 층(`spec` 바로 아래)에 둡니다.', 'kubectl apply -n $NS -f - <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: mc375-share
spec:
  volumes:
  - name: shared
    emptyDir: {}
  containers:
  - name: writer
    image: busybox:1.36
    command: ["sh", "-c", "echo hello > /data/msg.txt; sleep 3600"]
    volumeMounts:
    - name: shared
      mountPath: /data
  - name: reader
    image: busybox:1.36
    command: ["sh", "-c", "sleep 3600"]
    volumeMounts:
    - name: shared
      mountPath: /data
EOF
kubectl exec mc375-share -c reader -n $NS -- cat /data/msg.txt

# 같은 emptyDir 를 두 컨테이너가 마운트하면 한쪽이 쓴 파일을 다른 쪽이 읽는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod mc375-share -n $NS -o jsonpath=''{.spec.containers[*].name}'' 2>/dev/null)\\" = \\"writer reader\\" ] ) && ( [ \\"$(kubectl get pod mc375-share -n $NS -o jsonpath=''{.spec.volumes[0].name}-{.spec.volumes[0].emptyDir}'' 2>/dev/null)\\" = \\"shared-{}\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec mc375-share -c reader -n $NS -- cat /data/msg.txt 2>/dev/null)\\" = hello ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컨테이너 이름이 writer, reader 순서다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-share -n $NS -o jsonpath=''{.spec.containers[*].name}'' 2>/dev/null)\\" = \\"writer reader\\" ]"]}, {"label": "emptyDir 볼륨 shared 가 있다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-share -n $NS -o jsonpath=''{.spec.volumes[0].name}-{.spec.volumes[0].emptyDir}'' 2>/dev/null)\\" = \\"shared-{}\\" ]"]}, {"label": "reader 에서 /data/msg.txt 를 읽으면 hello 다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec mc375-share -c reader -n $NS -- cat /data/msg.txt 2>/dev/null)\\" = hello ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 6, '앱보다 먼저 도는 준비 컨테이너 (initContainers)', '**배경** — `initContainers` 는 앱 컨테이너가 시작되기 **전에** 차례로 실행되고, **성공해서 끝나야** 앱 컨테이너가 시작됩니다. 설정 파일 준비, 다른 서비스 기다리기 같은 사전 작업에 씁니다.

**문제** — Pod **`mc375-init`** 을 YAML 로 만드세요. ① `emptyDir` 볼륨 **`work`**. ② init 컨테이너 **`prep`**(`busybox:1.36`)은 `work` 를 `/work` 에 마운트하고 `echo ready > /work/state.txt` 를 실행하고 끝납니다. ③ 앱 컨테이너 **`app`**(`busybox:1.36`)은 `work` 를 `/work` 에 마운트하고 `cat /work/state.txt; sleep 3600` 을 실행합니다. `app` 의 로그에 `ready` 가 보여야 합니다.', '`initContainers:` 는 `containers:` 와 같은 층에 따로 적습니다. 두 컨테이너가 같은 `work` 볼륨을 `/work` 에 마운트해야 `prep` 이 쓴 파일을 `app` 이 읽을 수 있어요.', 'kubectl apply -n $NS -f - <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: mc375-init
spec:
  volumes:
  - name: work
    emptyDir: {}
  initContainers:
  - name: prep
    image: busybox:1.36
    command: ["sh", "-c", "echo ready > /work/state.txt"]
    volumeMounts:
    - name: work
      mountPath: /work
  containers:
  - name: app
    image: busybox:1.36
    command: ["sh", "-c", "cat /work/state.txt; sleep 3600"]
    volumeMounts:
    - name: work
      mountPath: /work
EOF
kubectl logs mc375-init -c app -n $NS

# init 컨테이너가 끝난 뒤에야 app 이 시작되고, 같은 emptyDir 로 결과를 넘긴다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod mc375-init -n $NS -o jsonpath=''{.spec.initContainers[0].name}'' 2>/dev/null)\\" = \\"prep\\" ] ) && ( [ \\"$(kubectl get pod mc375-init -n $NS -o jsonpath=''{.spec.containers[0].name}'' 2>/dev/null)\\" = \\"app\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl logs mc375-init -c app -n $NS 2>/dev/null)\\" = ready ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "init 컨테이너 이름이 prep 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-init -n $NS -o jsonpath=''{.spec.initContainers[0].name}'' 2>/dev/null)\\" = \\"prep\\" ]"]}, {"label": "앱 컨테이너 이름이 app 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-init -n $NS -o jsonpath=''{.spec.containers[0].name}'' 2>/dev/null)\\" = \\"app\\" ]"]}, {"label": "app 의 로그가 ready 다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl logs mc375-init -c app -n $NS 2>/dev/null)\\" = ready ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 7, 'Init 에서 멈춘 Pod 의 원인 컨테이너 찾기', 'Pod **`mc375-stuck`** 의 STATUS 가 `Init:0/1` 에서 계속 멈춰 있습니다(앱 컨테이너는 시작하지 못했습니다). 어느 **init 컨테이너의 이름** 이 끝나지 않고 있는지 찾아 **`/tmp/q7.txt`** 에 저장하세요.', '`kubectl get pod mc375-stuck` 의 STATUS 를 보고, `kubectl describe pod mc375-stuck` 의 `Init Containers:` 항목이나 `-o jsonpath=''{.spec.initContainers[*].name}''` 로 init 컨테이너 이름을 확인하세요.', 'kubectl get pod mc375-stuck -n $NS     # STATUS Init:0/1
kubectl describe pod mc375-stuck -n $NS | grep -A6 ''Init Containers''
kubectl get pod mc375-stuck -n $NS -o jsonpath=''{.spec.initContainers[0].name}'' > /tmp/q7.txt
cat /tmp/q7.txt

# Init:0/1 은 init 컨테이너 1개 중 0개가 끝났다는 뜻이다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-stuck\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  initContainers:\\n  - name: wait-for-db\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"until [ -f /tmp/never ]; do sleep 2; done\\"]\\n  containers:\\n  - name: app\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n---\\nEOF\\n( i=0; while [ $i -lt 60 ]; do if [ -n \\"$(kubectl get pod mc375-stuck -n $NS -o jsonpath=''{.status.initContainerStatuses[0].name}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ); true"]', '["sh", "-c", "( [ \\"$(cat /tmp/q7.txt)\\" = wait-for-db ] ) && ( [ \\"$(kubectl get pod mc375-stuck -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Pending\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q7.txt 가 끝나지 않는 init 컨테이너 이름(wait-for-db)이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q7.txt)\\" = wait-for-db ]"]}, {"label": "Pod 는 아직 Init 에서 멈춘 채 그대로 있다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod mc375-stuck -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Pending\\" ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 8, '준비된 컨테이너만 골라 보기', 'Pod **`mc375-mixed`** 는 컨테이너가 둘이고 READY 가 `1/2` 입니다(하나는 계속 실패합니다). **준비(Ready)된 컨테이너의 이름만** 출력하는 `-o jsonpath` 를 만들어 **`/tmp/q8.txt`** 에 저장하세요.', '`.status.containerStatuses` 에 컨테이너마다 `ready` 값이 있습니다. jsonpath 의 필터 `[?(@.ready==true)]` 로 거른 뒤 `.name` 을 뽑으세요.', 'kubectl get pod mc375-mixed -n $NS      # READY 1/2
kubectl get pod mc375-mixed -n $NS -o jsonpath=''{.status.containerStatuses[?(@.ready==true)].name}'' > /tmp/q8.txt
cat /tmp/q8.txt

# containerStatuses 의 ready 가 true 인 컨테이너만 거른다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-mixed\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - name: ok\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n  - name: bad\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"exit 1\\"]\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod/mc375-mixed -n $NS --timeout=90s >/dev/null 2>&1; ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod mc375-mixed -n $NS -o jsonpath=''{.status.containerStatuses[?(@.ready==true)].name}'' 2>/dev/null)\\" = ok ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ); true"]', '["sh", "-c", "( [ \\"$(cat /tmp/q8.txt)\\" = ok ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q8.txt 가 준비된 컨테이너 이름(ok)이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q8.txt)\\" = ok ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 9, '모든 컨테이너의 로그를 한 번에 (--all-containers)', 'Pod **`mc375-all`** 의 컨테이너 `first` 와 `second` 가 각자 한 줄씩 출력했습니다. **컨테이너 이름을 하나하나 지정하지 않고** 모든 컨테이너의 로그를 한 번에 읽어 **`/tmp/q9.txt`** 에 저장하세요.', '`kubectl logs --help` 에 Pod 의 모든 컨테이너 로그를 가져오는 옵션이 있습니다. 이름에 `all` 이 들어 있어요.', 'kubectl logs mc375-all --all-containers=true -n $NS > /tmp/q9.txt
cat /tmp/q9.txt

# --all-containers 는 Pod 의 모든 컨테이너 로그를 이어서 보여 준다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete pod -l etude=lab375 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod mc375-two mc375-share mc375-init -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: mc375-all\\n  labels:\\n    etude: lab375\\nspec:\\n  terminationGracePeriodSeconds: 0\\n  containers:\\n  - name: first\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo from-first; sleep 3600\\"]\\n  - name: second\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo from-second; sleep 3600\\"]\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod/mc375-all -n $NS --timeout=90s >/dev/null 2>&1; sleep 2; true"]', '["sh", "-c", "( [ \\"$(sort /tmp/q9.txt)\\" = \\"$(printf \\"from-first\\\\nfrom-second\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 에 두 컨테이너의 로그(from-first, from-second)가 모두 있다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/q9.txt)\\" = \\"$(printf \\"from-first\\\\nfrom-second\\")\\" ]"]}]', '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 10, 'init 컨테이너는 언제 실행될까?', 'Pod 에 `initContainers` 와 앱 `containers` 가 함께 있을 때, 실행 순서는 어떻게 될까요?', '"init" 은 "시작 전 준비"라는 뜻입니다.', NULL, NULL, '[]', 'choice', '["init 컨테이너와 앱 컨테이너가 동시에 시작해 함께 실행된다", "init 컨테이너가 먼저 차례로 실행되어 성공해야 앱 컨테이너가 시작된다", "앱 컨테이너가 모두 끝난 뒤에 init 컨테이너가 실행된다", "init 컨테이너가 실패해도 앱 컨테이너는 그대로 시작한다"]', 1, 'init 컨테이너는 앱 컨테이너보다 **먼저**, 정의한 **순서대로 하나씩** 끝까지 실행되고, 모두 성공해야 앱 컨테이너가 시작됩니다. init 컨테이너가 끝나지 않거나 실패하면 Pod 는 `Init:...` 상태에 머뭅니다.', NULL, NULL, NULL, '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 11, '컨테이너를 고르는 옵션', 'Pod `mc375-logs` 의 `sidecar` 컨테이너 로그만 보는 명령입니다. 빈칸을 채우세요.', '"container"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-c", "--ctr", "-x", "-m"]', NULL, '`kubectl logs 파드 -c 컨테이너이름` (`--container` 와 같음)으로 Pod 안의 컨테이너를 고릅니다. `kubectl exec` 도 같은 `-c` 를 씁니다. `--ctr`·`-x`·`-m` 은 이 자리에 쓰는 옵션이 아닙니다.', '[0]', 'kubectl logs mc375-logs {0} sidecar', NULL, '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]'),
  (375, 12, 'init 컨테이너가 있는 Pod 가 뜨는 흐름', 'init 컨테이너가 있는 Pod 가 만들어져 앱이 돌기까지의 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 준비 컨테이너 → 앱 컨테이너 → 상태 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl apply` 로 Pod 를 만든다", "init 컨테이너가 차례로 실행되어 성공한다 (`Init:N/M` 표시)", "앱 컨테이너들이 시작된다", "`kubectl get pod` 에서 `Running` 과 READY 를 확인한다"]', NULL, 'Pod 를 만들면 init 컨테이너가 정해진 순서대로 끝까지 실행됩니다(그동안 STATUS 는 `Init:N/M`). 모두 성공하면 앱 컨테이너가 시작되고, `Running` 과 READY 로 확인합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Init 컨테이너", "url": "https://kubernetes.io/docs/concepts/workloads/pods/init-containers/"}, {"title": "파드(Pod)", "url": "https://kubernetes.io/docs/concepts/workloads/pods/"}, {"title": "볼륨(emptyDir)", "url": "https://kubernetes.io/docs/concepts/storage/volumes/"}, {"title": "같은 파드의 컨테이너가 볼륨으로 통신하기", "url": "https://kubernetes.io/docs/tasks/access-application-cluster/communicate-containers-same-pod-shared-volume/"}, {"title": "kubectl logs", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/"}]');
